import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'chat_screen.dart';
class ConnectScreen extends StatelessWidget { const ConnectScreen({super.key});
 @override Widget build(BuildContext context){ final client=Supabase.instance.client; final uid=client.auth.currentUser!.id; return SafeArea(child:Scaffold(body:StreamBuilder<List<Map<String,dynamic>>>(stream:client.from('help_connections').stream(primaryKey:['id']).order('created_at',ascending:false),builder:(context,s){if(s.hasError)return Center(child:Text('Unable to load connections: ${s.error}')); if(!s.hasData)return const Center(child:CircularProgressIndicator()); final rows=s.data!.where((r)=>r['requester_id']==uid||r['helper_id']==uid).toList(); return ListView(padding:const EdgeInsets.all(16),children:[Text('My Connections',style:Theme.of(context).textTheme.displaySmall),const SizedBox(height:8),const Text('People you have been matched with through Help Exchange.'),const SizedBox(height:20),if(rows.isEmpty)const Padding(padding:EdgeInsets.only(top:80),child:Center(child:Text('No active connections yet.'))),...rows.map((r)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.handshake)),title:Text('Help connection'),subtitle:Text((r['status']??'in progress').toString().replaceAll('_',' ')),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ChatScreen(connectionId:r['id'].toString(),title:'Sisonke Connection'))))))]);}))); }
}
